import unittest

from rotate import rotate


class RotateTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(rotate([], 4), [])

    def test_zero_and_exact_length_steps(self):
        self.assertEqual(rotate([1, 2, 3], 0), [1, 2, 3])
        self.assertEqual(rotate([1, 2, 3], 3), [1, 2, 3])
        self.assertEqual(rotate([1, 2, 3], -3), [1, 2, 3])

    def test_rotate_right(self):
        self.assertEqual(rotate([1, 2, 3, 4], 1), [4, 1, 2, 3])
        self.assertEqual(rotate([1, 2, 3, 4], 2), [3, 4, 1, 2])

    def test_negative_steps_rotate_left(self):
        self.assertEqual(rotate([1, 2, 3, 4], -1), [2, 3, 4, 1])
        self.assertEqual(rotate([1, 2, 3, 4], -2), [3, 4, 1, 2])

    def test_large_positive_and_negative_steps_wrap(self):
        self.assertEqual(rotate([1, 2, 3, 4], 9), [4, 1, 2, 3])
        self.assertEqual(rotate([1, 2, 3, 4], -9), [2, 3, 4, 1])

    def test_single_item(self):
        self.assertEqual(rotate(["only"], 100), ["only"])

    def test_accepts_iterable(self):
        self.assertEqual(rotate(iter([1, 2, 3]), 1), [3, 1, 2])

    def test_returns_new_list_without_mutating_input(self):
        items = [1, 2, 3]
        result = rotate(items, 1)
        self.assertEqual(items, [1, 2, 3])
        self.assertEqual(result, [3, 1, 2])
        self.assertIsNot(result, items)

    def test_rejects_non_integer_steps(self):
        for steps in (True, False, 1.5, "1", None):
            with self.subTest(steps=steps):
                with self.assertRaises(ValueError):
                    rotate([1, 2], steps)


if __name__ == "__main__":
    unittest.main()
